 try{enabled=localStorage.getItem('drift-atlas:faction-overlay')==='true';}catch{}
 const dialog=document.createElement('dialog');dialog.id='factions-dialog';dialog.innerHTML=`<div class="library-heading"><div><div class="eyebrow">POLITICAL CARTOGRAPHY</div><h2>Factions<span class="accent">.</span></h2></div><button id="close-factions" class="button">← Menu</button></div><p class="help">Assign individual planets, stations, moons, and other orbitals, or assign an entire system or sector. Systems with multiple orbital owners are contested.</p><div class="faction-editor"><label class="field">FACTION<select id="faction-select"></select></label><div class="faction-fields"><label class="field">NAME<input id="faction-name" maxlength="60" placeholder="Faction name"></label><label class="field">COLOR<input id="faction-color" type="color" value="#79dbcf"></label></div><div class="faction-actions"><button id="faction-save" class="primary">Create faction</button><button id="faction-delete" class="button">Delete faction</button></div></div><h3>Assign locations</h3><label class="field">ASSIGN BY<select id="faction-scope"><option value="orbital">Orbital</option><option value="system">System</option><option value="sector">Sector</option></select></label><label class="field">FIND A LOCATION<input id="faction-search" placeholder="Search locations…"></label><label class="field">LOCATION<select id="faction-target" size="7"></select></label><p id="faction-target-info" class="help"></p><div class="faction-actions"><button id="faction-assign" class="primary">Assign to faction</button><button id="faction-clear" class="button">Clear ownership</button></div><p id="faction-status" role="status" class="help"></p><div id="faction-summary"></div>`;document.body.append(dialog);
 const state=()=>{const catalog=factionCatalog(getData()),nodes=getNodes(),saved=getSaved();return {catalog,nodes,saved,model:factionModel(getAll(),nodes,saved,catalog)};};
 function refresh(){cache=null;invalidate();if(dialog.open)render();}
 async function changed(message){refresh();const ok=await commit();$('#faction-status').textContent=ok?message:'Could not save on this device. Export your map from Save / Load.';}
 function render(){const {catalog}=state();if(!catalog[active])active='';$('#faction-select').innerHTML='<option value="">＋ New faction</option>'+Object.entries(catalog).map(([id,f])=>`<option value="${esc(id)}">${esc(f.name)}</option>`).join('');$('#faction-select').value=active;$('#faction-name').value=catalog[active]?.name||'';$('#faction-color').value=catalog[active]?.color||'#79dbcf';$('#faction-save').textContent=active?'Save faction':'Create faction';$('#faction-delete').disabled=!active;targets();summary();}
 function targets(){const {catalog,nodes,saved,model}=state(),scope=$('#faction-scope').value,search=$('#faction-search').value.toLowerCase(),prior=$('#faction-target').value;let choices=[];const locationName=n=>(getData()._driftAtlasCluster?(getData().sector?.[n.parent]?.name||'Sector')+' / ':'')+n.name;
 if(scope==='orbital')for(const n of nodes)for(const body of model.systems.get(n.id))choices.push({id:body.id,name:`${locationName(n)} / ${body.name} · ${body.type.replace(/([a-z])([A-Z])/g,'$1 $2').toLowerCase()} — ${locationOwners(saved[body.id],catalog).map(id=>catalog[id].name).join(' / ')||'Unclaimed'}`});
 if(scope==='system')choices=nodes.map(n=>({id:n.id,name:locationName(n)+' — '+(model.owners.get(n.id).map(id=>catalog[id].name).join(' / ')||'Unclaimed')}));
 if(scope==='sector')choices=Object.entries(getData().sector||{}).map(([id,s])=>({id,name:s.name}));
 $('#faction-target').innerHTML=choices.filter(c=>c.name.toLowerCase().includes(search)).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');if([...$('#faction-target').options].some(o=>o.value===prior))$('#faction-target').value=prior;else $('#faction-target').selectedIndex=0;targetInfo();}
 function selectedTargets(){const {nodes,model}=state(),scope=$('#faction-scope').value,id=$('#faction-target').value;if(!id)return [];if(scope==='orbital')return [id];const stars=scope==='system'?nodes.filter(n=>n.id===id):nodes.filter(n=>n.parent===id);return stars.flatMap(n=>[n.id,...model.systems.get(n.id).map(o=>o.id)]);}
 function targetInfo(){const ids=selectedTargets();$('#faction-target-info').textContent=$('#faction-scope').value==='orbital'?'Changes only this orbital.':'Replaces ownership of the system(s) and all their orbitals.';$('#faction-assign').disabled=!active||!ids.length;$('#faction-clear').disabled=!ids.length;}
 function summary(){const {catalog,model}=state();$('#faction-summary').innerHTML='<h3>Territory</h3>'+Object.entries(catalog).map(([id,f])=>`<p><i class="faction-swatch" style="background:${f.color}"></i>${esc(f.name)} · ${[...model.owners.values()].filter(a=>a.includes(id)).length} systems</p>`).join('')+`<p class="help">${[...model.owners.values()].filter(a=>a.length>1).length} contested systems · stripes show every controlling faction.</p>`;}
 $('#faction-select').onchange=e=>{active=e.target.value;render();};$('#faction-scope').onchange=targets;$('#faction-search').oninput=targets;$('#faction-target').onchange=targetInfo;
 $('#faction-save').onclick=async()=>{const name=$('#faction-name').value.trim();if(!name){$('#faction-status').textContent='Enter a faction name.';return;}const d=getData();d._driftAtlas||={};d._driftAtlas.factions||={};active||=crypto.randomUUID();d._driftAtlas.factions[active]={name,color:$('#faction-color').value};await changed('Faction saved.');};
