 for(const action of ['assign','clear'])$('#faction-'+action).onclick=async()=>{const ids=selectedTargets();if(action==='assign'&&!active)return;const saved=getSaved();for(const id of ids){saved[id]||={};setLocationOwners(saved[id],action==='assign'?[active]:[]);}await changed('Ownership saved.');};
 function toggle(value){enabled=value;for(const el of document.querySelectorAll('[data-faction-toggle],#faction-overlay'))el.checked=value;try{localStorage.setItem('drift-atlas:faction-overlay',String(value));}catch{}invalidate();}
