 async function handleDetails(event){const el=event.target;if(!el.matches('select[data-owner-id]'))return;const id=el.dataset.ownerId,type=el.dataset.ownerType,value=el.value,{catalog,model,saved}=state();if(value&&!catalog[value])return;const ids=['system','blackHole'].includes(type)?[id,...(model.systems.get(id)||[]).map(n=>n.id)]:[id];for(const key of ids){saved[key]||={};setLocationOwners(saved[key],value?[value]:[]);}refresh();const status=el.closest('.location-faction').querySelector('.owner-save-status');status.textContent='Saving…';for(const select of document.querySelectorAll('#dossier [data-owner-id]')){const n={id:select.dataset.ownerId,type:select.dataset.ownerType};select.innerHTML=detailOptions(n);select.value=detailValue(n);}const ok=await commit();status.textContent=ok?'Ownership saved.':'Could not save. Export your map from Save / Load.';}
 return {details,handleDetails,open(){render();$('#faction-status').textContent='Changes save automatically with this map.';dialog.showModal();},refresh,draw(ctx,project,visible,labelOpacity=1){labelPlans=[];if(!enabled)return [];const {catalog,nodes,model}=state();const visibleNodes=nodes.filter(visible),key=visibleNodes.map(n=>n.id).join('|');if(!cache||key!==cacheKey){cache=[...territoryCells(visibleNodes,model.owners).map(c=>({...c,labelEligible:model.complete.has(c.n.id)})),...laneTerritories(visibleNodes,model.owners,getLanes())];cacheKey=key;}lastOwners=model.owners;lastCatalog=catalog;labelPlans=drawTerritories(ctx,cache,catalog,project,{labels:document.querySelector('#labels')?.checked!==false,paintLabels:false,labelOpacity});return labelPlans;},drawLabels(ctx){for(const label of labelPlans)paintTerritoryLabel(ctx,label,label.color);},colors(id){if(!enabled)return [];return (lastOwners.get(id)||[]).map(key=>lastCatalog[key].color);}};
